SourceCode.Declaration:
/// <summary>
/// Chain of Command extension on <c>CustTable</c> to detect customer creation and updates
/// and enqueue eligible B2C customers into <c>UTCSFCustomerPushQueue</c>.
/// </summary>
[ExtensionOf(tableStr(CustTable))]
public final class UTCSFCustTable_Extension
{
}

Method.Source:
public void update()
{
    CustTable origCustTable = this.orig();

    boolean hasRelevantChange = (this.CustGroup  != origCustTable.CustGroup
                              || this.Blocked    != origCustTable.Blocked
                              || this.Party      != origCustTable.Party
                              || this.AccountNum != origCustTable.AccountNum);

    next update();

    if (hasRelevantChange)
    {
        UTCSFCustomerChangeHandler::tryEnqueueCustTable(this);
    }
}
